spec.expr:
sum by (service) (
  label_replace(
    sum_over_time(
      aws_applicationelb_request_count_sum{
        dimension_LoadBalancer=~"app/fc-$stage/.*",
        dimension_AvailabilityZone="",
        dimension_TargetGroup=~"targetgroup/fc-$stage-($service)/.*"
      }[$__interval]
    ),
    "service", "$1", "dimension_TargetGroup", "targetgroup/fc-$stage-([^/]+)/.*"
  )
) / ($__interval_ms / 60000)
